// How do I update the filtered view after data has changed in a spreadsheet?

// Refresh the visible rows without changing or removing the filter conditions in a spreadsheet.

let worksheet = Api.GetActiveSheet();

// Prepare sample data
worksheet.GetRange("A1").SetValue("Score");
worksheet.GetRange("A2").SetValue(10);
worksheet.GetRange("A3").SetValue(20);
worksheet.GetRange("A4").SetValue(30);
worksheet.GetRange("A5").SetValue(40);
worksheet.GetRange("A6").SetValue(50);

// Apply an AutoFilter that shows values greater than 25
let dataRange = worksheet.GetRange("A1:A6");
dataRange.SetAutoFilter(null);
dataRange.SetAutoFilter(1, ">25", "xlOr");

// Change one value so that the filter result would be different
worksheet.GetRange("A7").SetValue(22);

// Reapply the existing filter criteria on the worksheet
let autoFilter = worksheet.AutoFilter;
autoFilter.ApplyFilter();

// Explain in the sheet what we did
worksheet.GetRange("C1").SetValue("AutoFilter reapplied with ApplyFilter().");
worksheet.GetRange("C2").SetValue("Filter: Score > 25");
worksheet.GetRange("C7").SetValue("Updated value in A3 is now included by the filter.");

// How do I tell if a filter is hiding rows on a sheet in a spreadsheet?

// Confirm that at least one filtering rule is in effect and some data is being suppressed in a spreadsheet.

let worksheet = Api.GetActiveSheet();

// Initially: no AutoFilter
let autoFilter = worksheet.AutoFilter;

worksheet.GetRange("C1").SetValue("FilterMode before SetAutoFilter:");
worksheet.GetRange("C2").SetValue(autoFilter.FilterMode);

// Add data and apply an AutoFilter
worksheet.GetRange("A1").SetValue("Data");
worksheet.GetRange("A2").SetValue(1);
worksheet.GetRange("A3").SetValue(2);
worksheet.GetRange("A4").SetValue(3);
worksheet.GetRange("A5").SetValue(4);

let dataRange = worksheet.GetRange("A1:A5");
dataRange.SetAutoFilter(1, ">2", "xlOr");

// Reacquire the AutoFilter and check FilterMode again
autoFilter = worksheet.AutoFilter;

worksheet.GetRange("C4").SetValue("FilterMode after SetAutoFilter:");
worksheet.GetRange("C5").SetValue(autoFilter.GetFilterMode());

// How do I read the criteria that each column filter is using in a spreadsheet?

// Inspect what values or rules each column is being filtered by in a spreadsheet.

let worksheet = Api.GetActiveSheet();

// Prepare sample data
worksheet.GetRange("A1").SetValue("Value");
worksheet.GetRange("A2").SetValue(2);
worksheet.GetRange("A3").SetValue(5);
worksheet.GetRange("A4").SetValue(7);
worksheet.GetRange("A5").SetValue(9);
worksheet.GetRange("A6").SetValue(11);

// Apply a values filter on column A
let dataRange = worksheet.GetRange("A1:A6");
dataRange.SetAutoFilter(1, ["2", "5", "7"], "xlFilterValues");

// Get the AutoFilter and its filters collection
let autoFilter = worksheet.AutoFilter;
let filters = autoFilter.GetFilters();      // or autoFilter.Filters

worksheet.GetRange("C1").SetValue("Number of filters:");
worksheet.GetRange("C2").SetValue(filters.length);

// Show information about the first filter
if (filters.length > 0) {
    let f = filters[0];

    worksheet.GetRange("C4").SetValue("Operator:");
    worksheet.GetRange("C5").SetValue(f.Operator);

    worksheet.GetRange("C7").SetValue("Criteria1:");
    worksheet.GetRange("C8").SetValue(f.Criteria1.toString());

    worksheet.GetRange("C10").SetValue("Filter On:");
    worksheet.GetRange("C11").SetValue(f.On);
}

// How do I get back to the sheet itself when I only have a filter reference in a spreadsheet?

// Navigate from the filter back to the worksheet so you can work with other cells on the same sheet in a spreadsheet.

let worksheet = Api.GetActiveSheet();

// Create a simple AutoFilter
worksheet.GetRange("A1").SetValue("Name");
worksheet.GetRange("A2").SetValue("Alice");
worksheet.GetRange("A3").SetValue("Bob");
worksheet.GetRange("A4").SetValue("Charlie");

let range = worksheet.GetRange("A1:A4");
range.SetAutoFilter();

// Get the AutoFilter and its parent worksheet
let autoFilter = worksheet.AutoFilter;
let parentSheet = autoFilter.GetParent();   // or autoFilter.Parent

worksheet.GetRange("C1").SetValue("Parent worksheet name:");
worksheet.GetRange("C2").SetValue(parentSheet.GetName());

worksheet.GetRange("C4").SetValue("AutoFilter is attached to this worksheet.");

// How do I get the cell range that the current filter is applied to in a spreadsheet?

// Identify the full span of rows and columns under filter control so you can format or read them in a spreadsheet.

let worksheet = Api.GetActiveSheet();

// Prepare a header and some data
worksheet.GetRange("A1").SetValue("Product");
worksheet.GetRange("B1").SetValue("Quantity");

worksheet.GetRange("A2").SetValue("Apples");
worksheet.GetRange("B2").SetValue(10);
worksheet.GetRange("A3").SetValue("Oranges");
worksheet.GetRange("B3").SetValue(20);
worksheet.GetRange("A4").SetValue("Bananas");
worksheet.GetRange("B4").SetValue(5);

// Apply an AutoFilter to A1:B4
let dataRange = worksheet.GetRange("A1:B4");
dataRange.SetAutoFilter(2, ">8", "xlAnd");

// Get the AutoFilter range
let autoFilter = worksheet.AutoFilter;
let filterRange = autoFilter.GetRange();    // or autoFilter.Range

worksheet.GetRange("D1").SetValue("AutoFilter range address:");
if (filterRange !== null) {
    worksheet.GetRange("D2").SetValue(filterRange.GetAddress());
    // Highlight the AutoFilter range
    filterRange.SetFillColor(Api.CreateColorFromRGB(255, 255, 204));
} else {
    worksheet.GetRange("D2").SetValue("No AutoFilter defined.");
}

// How do I unhide all filtered-out rows without removing the filter drop-downs in a spreadsheet?

// Reveal all hidden rows while leaving the filter controls on the header intact in a spreadsheet.

let worksheet = Api.GetActiveSheet();

// Prepare sample data
worksheet.GetRange("A1").SetValue("Amount");
worksheet.GetRange("A2").SetValue(10);
worksheet.GetRange("A3").SetValue(200);
worksheet.GetRange("A4").SetValue(50);
worksheet.GetRange("A5").SetValue(300);
worksheet.GetRange("A6").SetValue(40);

// Apply an AutoFilter that hides small values
let dataRange = worksheet.GetRange("A1:A6");
dataRange.SetAutoFilter(1, ">100", "xlOr");

let autoFilter = worksheet.AutoFilter;
worksheet.GetRange("C1").SetValue("FilterMode before ShowAllData:");
worksheet.GetRange("C2").SetValue(autoFilter.FilterMode);

// Now show all data (rows become visible, filter drop-down stays)
autoFilter.ShowAllData();

worksheet.GetRange("C4").SetValue("ShowAllData() called.");
worksheet.GetRange("C5").SetValue("Filter drop-down remains on header.");
worksheet.GetRange("C6").SetValue("All rows in the AutoFilter range are visible.");
